from setta.tasks.fns import InteractiveTaskDefinition


def fn(project):
    c = float(project["c"])
    n = int(project["n"])
    data = [(i, ((i - 10) / 5) ** c) for i in range(n)]
    headers = ["x", "y"]
    return {
        "simple list": {
            "value": {"headers": headers, "data": data},
            "type": "list",
            "name": "simple list",
        }
    }


interactive_example = InteractiveTaskDefinition(fn=fn)
